class BfmeBaseESO
{
public:
	int m_bfmeAESO;
	int m_bfmeBESO;
};

class BfmeSubAESO
{
public:
	void bfmeSwapESO(BfmeSubAESO &other);

	unsigned char m_bfmeBodyESO[0x20];
};

class BfmeSubBESO
{
public:
	void bfmeSwapESO(BfmeSubBESO &other);

	unsigned char m_bfmeBodyESO[4];
};

class BfmeHostESO;

void __stdcall bfmeAdjustESO(BfmeHostESO *other, BfmeBaseESO *ob, BfmeBaseESO *tb);

class BfmeHostESO : public BfmeFirstESO, public BfmeBaseESO
{
public:
	void bfmeSwapESO(BfmeHostESO *other);
	void bfmeFixupESO();
	void bfmeFinishESO(BfmeHostESO *other, int *a, int *b);

	BfmeSubAESO m_bfmeSubAESO;
	BfmeSubBESO m_bfmeSubBESO;
};

void BfmeHostESO::bfmeSwapESO(BfmeHostESO *other)
{
	BfmeHostESO *self = this;
	BfmeBaseESO *tb = (BfmeBaseESO *)((char *)self + 4);

	int a = other->m_bfmeAESO;
	int b = tb->m_bfmeAESO;

	tb->m_bfmeAESO = a;
	other->m_bfmeAESO = b;

	int c = other->m_bfmeBESO;
	int d = tb->m_bfmeBESO;

	tb->m_bfmeBESO = c;
	other->m_bfmeBESO = d;

	self->m_bfmeSubAESO.bfmeSwapESO(other->m_bfmeSubAESO);
	self->m_bfmeSubBESO.bfmeSwapESO(other->m_bfmeSubBESO);

	self->bfmeFixupESO();

	bfmeAdjustESO(other, (BfmeBaseESO *)((char *)other + 4), tb);

	self->bfmeFinishESO(other, &other->m_bfmeBESO, &self->m_bfmeBESO);
}
